# -*- coding: utf-8 -*-
"""Build the profile README visuals.

One spec, two themes. Every visual is written to assets/<name>.svg (light) and
assets/dark/<name>.svg, so the README can serve them through <picture> and
prefers-color-scheme without depending on any widget service.

What is NOT built here, on purpose:
  * the project recap  -> a markdown table in README.md, so the rows are real
    links and stay readable when the image is scaled down;
  * the stack grid     -> devicon <img> tags in README.md;
  * the contribution snake -> generated by .github/workflows/snake.yml into the
    `output` branch.

Run:  python tools/build.py
"""

from __future__ import annotations

import os
from xml.sax.saxutils import escape

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
W = 846  # GitHub's README column on desktop

# Backgrounds stay transparent so the visuals sit on whatever GitHub theme the
# reader uses, including the dimmed one. Only ink colours differ per theme.
THEMES = {
    "light": dict(ink="#1f2328", muted="#59636e", line="#d1d9e0",
                  accent="#8a5a00", wash="#f6f8fa", band="#eaeef2",
                  mark="#241206", markfg="#fbefd8"),
    "dark": dict(ink="#e6edf3", muted="#9198a1", line="#3d444d",
                 accent="#d9a441", wash="#161b22", band="#21262d",
                 mark="#fbefd8", markfg="#241206"),
}

MONO = "ui-monospace, SFMono-Regular, Menlo, Consolas, monospace"
SANS = "-apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif"


# ---------------------------------------------------------------- primitives

def svg(height: int, body: str) -> str:
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{height}" '
        f'viewBox="0 0 {W} {height}" role="img">\n{body}</svg>\n'
    )


def text(x, y, s, *, size=24, fill="ink", font=SANS, weight=400,
         anchor="start", spacing=0, t=None) -> str:
    a = [f'x="{x}"', f'y="{y}"', f'font-family="{font}"', f'font-size="{size}"',
         f'font-weight="{weight}"', f'fill="{t[fill] if fill in t else fill}"']
    if anchor != "start":
        a.append(f'text-anchor="{anchor}"')
    if spacing:
        a.append(f'letter-spacing="{spacing}"')
    return f'  <text {" ".join(a)}>{escape(s)}</text>\n'


def rule(x1, y, x2, t, *, stroke="line", width=1, dash=None) -> str:
    d = f' stroke-dasharray="{dash}"' if dash else ""
    return (f'  <line x1="{x1}" y1="{y}" x2="{x2}" y2="{y}" '
            f'stroke="{t[stroke]}" stroke-width="{width}"{d}/>\n')


def rect(x, y, w, h, t, *, fill=None, stroke="line", rx=6, width=1) -> str:
    f = t[fill] if fill else "none"
    s = t[stroke] if stroke else "none"
    return (f'  <rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" '
            f'fill="{f}" stroke="{s}" stroke-width="{width}"/>\n')


# --------------------------------------------------------------------- hero

# The portfolio mark, straight out of portfolio-website/src/app/icon.svg: a
# diamond with a vertical slot cut through it, drawn with fill-rule evenodd.
MARK = ("M 128 30 L 226 128 L 128 226 L 30 128 Z "
        "M 108 70 L 148 70 L 148 186 L 108 186 Z")


def hero(t) -> str:
    """Animated mark on the left, name on the right.

    CSS keyframes, not SMIL and not JS: an <img>-loaded SVG runs no script.
    Opacity carries the animation and the transform only adds to it, so the
    mark is still legible wherever SVG transforms are ignored.
    """
    panel = 300
    css = (
        ".mk{transform-box:fill-box;transform-origin:center;"
        "animation:rise 6s ease-in-out infinite}"
        "@keyframes rise{0%{opacity:.18;transform:scale(.90) rotate(-8deg)}"
        "20%{opacity:1;transform:scale(1) rotate(0)}"
        "82%{opacity:1;transform:scale(1) rotate(0)}"
        "100%{opacity:.18;transform:scale(.90) rotate(-8deg)}}"
        ".rg{transform-box:fill-box;transform-origin:center;"
        "animation:ring 6s ease-out infinite}"
        "@keyframes ring{0%{opacity:.5;transform:scale(.55)}"
        "55%{opacity:0;transform:scale(1.25)}100%{opacity:0;transform:scale(1.25)}}"
        "@media(prefers-reduced-motion:reduce){.mk,.rg{animation:none}"
        ".mk{opacity:1}.rg{opacity:0}}"
    )
    b = f'  <style>{css}</style>\n'
    b += rect(0, 0, panel, panel, t, fill="wash", rx=8)
    cx = panel / 2
    b += (f'  <circle class="rg" cx="{cx}" cy="150" r="104" fill="none" '
          f'stroke="{t["accent"]}" stroke-width="1.5"/>\n')
    # Placement and animation must live on SEPARATE elements. A CSS transform
    # replaces the transform attribute outright rather than composing with it,
    # so putting both on one <g> silently drops the translate and scale the
    # moment the animation starts.
    b += (f'  <g transform="translate({cx - 90} 60) scale(0.703)">'
          f'<g class="mk"><path fill-rule="evenodd" fill="{t["mark"]}" d="{MARK}"/></g>'
          f'</g>\n')

    nx = panel + 44
    b += text(nx, 92, "ILHAM", size=62, weight=700, spacing=-1, t=t)
    b += text(nx, 156, "BINTANG", size=62, weight=200, spacing=-1, fill="muted", t=t)
    b += text(nx, 220, "SATRIA", size=62, weight=700, spacing=-1, t=t)
    b += rule(nx, 252, W, t)
    b += text(nx, 286, "Data · Machine Learning · Surabaya", size=22, fill="muted", t=t)
    return svg(panel, b)


def band(num, label, t) -> str:
    b = rect(0, 0, W, 56, t, fill="band", stroke=None, rx=4)
    b += text(22, 37, num, size=24, weight=700, fill="accent", font=MONO, t=t)
    b += text(76, 37, "—", size=24, fill="muted", font=MONO, t=t)
    b += text(112, 37, label, size=24, weight=500, font=MONO, spacing=1, t=t)
    return svg(56, b)


def whoami(t) -> str:
    b = text(0, 38, "I like the whole chain: raw data, pipelines, statistics,", size=25, t=t)
    b += text(0, 74, "models, and the dashboard someone decides from.", size=25, t=t)
    b += text(0, 128, "What draws me is the reasoning under the tooling — what a", size=23,
              fill="muted", t=t)
    b += text(0, 162, "method assumes, and where that assumption breaks.", size=23,
              fill="muted", t=t)
    return svg(186, b)


# --------------------------------------------------------------- FIG. 01 map

# Branch label, then the repositories under it. Only repositories that are
# public, non-empty and safe to show.
# Hub and spokes. Each node is (repo, one-line subtitle); the groups are placed
# on the four sides of the hub so no two boxes ever collide.
MAP_TOP = ("FUNDAMENTALS", [
    ("XOR-Perceptron", "a boundary no line draws"),
    ("MLP-Digits", "8×8 grid · sklearn"),
])
MAP_LEFT = ("DATA ENGINEERING", [
    ("Medallion", "bronze → silver → gold"),
    ("EventDriven-Streaming", "Kafka · out-of-order"),
    ("Ingestion", "scheduled pulls"),
    ("Data-Quality", "6 dimensions · 3σ drift"),
])
MAP_RIGHT = ("MACHINE LEARNING", [
    ("ara-26", "segmentation · Kaggle"),
    ("RNN", "time series"),
    ("Goal-Scorer", "match prediction"),
    ("HeartClass", "clinical classification"),
])
MAP_BOTTOM = ("AGENTS & APPS", [
    ("agent", "7 scripts · knowledge OS"),
    ("Warungku", "stock · forecasting"),
])


def _node(x, y, name, sub, t, bw=198, bh=58) -> str:
    # Monospace runs ~0.6em per character, so 17px fits about 19 characters in
    # a 198px box. Longer repository names step down a size rather than spill.
    size = 17 if len(name) <= 19 else 14
    b = rect(x, y, bw, bh, t, fill="wash")
    b += text(x + bw / 2, y + 26, name, size=size, weight=700, font=MONO,
              anchor="middle", t=t)
    b += text(x + bw / 2, y + 46, sub, size=14, fill="muted", font=MONO,
              anchor="middle", t=t)
    return b


def system_map(t) -> str:
    """Hub and spokes, with the groups on the four sides of the centre."""
    H, bw, bh = 724, 198, 58
    hx, hy, hw, hh = 318, 326, 210, 72          # hub box
    cx, cy = hx + hw / 2, hy + hh / 2

    b = text(0, 26, "SYSTEM MAP — ONE PATH, RAW DATA TO DECISION",
             size=19, weight=700, font=MONO, spacing=1, t=t)
    b += text(W, 26, "FIG. 01", size=19, fill="muted", font=MONO, anchor="end", t=t)
    b += rule(0, 40, W, t)

    placed = []                                  # (x, y, name, sub)
    for i, (name, sub) in enumerate(MAP_TOP[1]):
        placed.append((206 + i * 264, 92, name, sub))
    for i, (name, sub) in enumerate(MAP_LEFT[1]):
        placed.append((8, 190 + i * 104, name, sub))
    for i, (name, sub) in enumerate(MAP_RIGHT[1]):
        placed.append((W - bw - 8, 190 + i * 104, name, sub))
    for i, (name, sub) in enumerate(MAP_BOTTOM[1]):
        placed.append((206 + i * 264, 620, name, sub))

    # Spokes first, so every line passes under the boxes it connects.
    for x, y, _, _ in placed:
        bx, by = x + bw / 2, y + bh / 2
        b += (f'  <path d="M{cx} {cy} L{bx} {by}" stroke="{t["line"]}" '
              f'stroke-width="1" fill="none"/>\n')

    for x, y, name, sub in placed:
        b += _node(x, y, name, sub, t)

    b += rect(hx, hy, hw, hh, t, fill="band", stroke="accent")
    b += text(cx, hy + 32, "YONOBENGKEL.SYS", size=19, weight=700, fill="accent",
              font=MONO, anchor="middle", t=t)
    b += text(cx, hy + 54, "32 public repositories", size=15, fill="muted",
              font=MONO, anchor="middle", t=t)

    lab = dict(size=15, weight=700, fill="accent", font=MONO, spacing=1)
    b += text(423, 74, MAP_TOP[0], anchor="middle", t=t, **lab)
    b += text(8, 174, MAP_LEFT[0], t=t, **lab)
    b += text(W - 8, 174, MAP_RIGHT[0], anchor="end", t=t, **lab)
    b += text(423, 700, MAP_BOTTOM[0], anchor="middle", t=t, **lab)
    return svg(H, b)


# --------------------------------------------------------- FIG. 02 telemetry

# Counted from the GitHub API on 2026-10-18 over non-fork public repositories.
# Primary language only, which is what the API reports per repository.
LANGS = [("jupyter notebook", 47), ("python", 31), ("typescript", 6),
         ("html", 6), ("other", 9)]
YEARS = [("2025", 6), ("2026", 26)]
# Cumulative repository count at each month that actually saw a new one.
GROWTH = [("'25", 2), ("", 3), ("", 6), ("'26", 8), ("", 10), ("", 24), ("oct", 32)]
BIG = [("32", "REPOSITORIES"), ("182", "PUBLIC COMMITS"),
       ("6", "FEATURED WORK"), ("3", "LIVE DEMOS")]
STATS = [("public repositories", "32"), ("public commits", "182"),
         ("pull requests", "1"), ("repos with a live demo", "3"),
         ("primary languages", "6")]
TOTAL_REPOS = 32


def telemetry(t) -> str:
    """Three columns over two panels, following the reference's arrangement.

    No "EST." anywhere: every figure here is counted from the GitHub API.
    """
    b = text(0, 26, "TELEMETRY — COUNTED, NOT ESTIMATED", size=19, weight=700,
             font=MONO, spacing=1, t=t)
    b += text(W, 26, "FIG. 02", size=19, fill="muted", font=MONO, anchor="end", t=t)
    b += rule(0, 40, W, t)

    sub = dict(size=15, weight=700, fill="muted", font=MONO, spacing=1)

    # --- column A: language share -------------------------------------
    b += text(0, 76, "LANGUAGE DISTRIBUTION", t=t, **sub)
    y, barw = 98, 196
    for name, pct in LANGS:
        b += text(0, y + 11, name, size=14, font=MONO, t=t)
        b += (f'  <rect x="0" y="{y + 18}" width="{barw}" height="9" rx="2" '
              f'fill="{t["line"]}"/>\n')
        b += (f'  <rect x="0" y="{y + 18}" width="{round(barw * pct / 47)}" height="9" '
              f'rx="2" fill="{t["accent"]}"/>\n')
        b += text(barw + 12, y + 27, f"{pct}%", size=14, font=MONO, fill="muted", t=t)
        y += 40

    # --- column B: cumulative growth ----------------------------------
    gx, gw = 300, 268
    b += text(gx, 76, "SHIPPING VELOCITY · 2025 → 2026", t=t, **sub)
    gy, gh = 104, 150
    top = GROWTH[-1][1]
    pts = []
    for i, (_, v) in enumerate(GROWTH):
        px = gx + round(gw * i / (len(GROWTH) - 1))
        py = gy + gh - round(gh * v / top)
        pts.append((px, py))
    b += rule(gx, gy + gh, gx + gw, t, stroke="line")
    b += (f'  <path d="M' + " L".join(f"{x} {y}" for x, y in pts) +
          f'" stroke="{t["accent"]}" stroke-width="2" fill="none"/>\n')
    for x, y in pts:
        b += f'  <circle cx="{x}" cy="{y}" r="3.5" fill="{t["accent"]}"/>\n'
    for i, (lab, _) in enumerate(GROWTH):
        if lab:
            b += text(pts[i][0], gy + gh + 22, lab, size=14, fill="muted",
                      font=MONO, anchor="middle", t=t)
    b += text(gx, gy + gh + 48, "cumulative — flat, then steep", size=14,
              fill="muted", font=MONO, t=t)

    # --- column C: headline counts ------------------------------------
    # 14px mono with 1px tracking runs ~9.4px per character, so the longest
    # label needs ~132px; starting the column at 598 keeps it inside 846.
    nx = 598
    ny = 92
    for num, lab in BIG:
        b += text(nx, ny + 30, num, size=40, weight=700, t=t)
        b += text(nx + 96, ny + 24, lab, size=14, fill="muted", font=MONO,
                  spacing=1, t=t)
        ny += 54

    # --- two panels ----------------------------------------------------
    py = 330
    pw = 406
    ph = 46 + len(STATS) * 32
    b += rect(0, py, pw, ph, t, fill=None)
    b += text(22, py + 32, "GITHUB STATS", t=t, **sub)
    yy = py + 62
    for k, v in STATS:
        b += text(22, yy, k, size=15, font=MONO, fill="muted", t=t)
        b += text(pw - 22, yy, v, size=15, weight=700, font=MONO, anchor="end", t=t)
        yy += 32

    b += rect(W - pw, py, pw, ph, t, fill=None)
    b += text(W - pw + 22, py + 32, "REPOSITORIES PER YEAR", t=t, **sub)
    yy = py + 68
    for name, v in YEARS:
        b += text(W - pw + 22, yy + 10, name, size=15, font=MONO, t=t)
        b += (f'  <rect x="{W - pw + 90}" y="{yy}" width="{round(252 * v / 26)}" '
              f'height="14" rx="3" fill="{t["accent"]}"/>\n')
        b += text(W - 22, yy + 12, str(v), size=15, weight=700, font=MONO,
                  anchor="end", t=t)
        yy += 42
    b += text(W - pw + 22, py + ph - 20, "forks not counted", size=13,
              fill="muted", font=MONO, t=t)
    return svg(py + ph + 24, b)


# ------------------------------------------------------------ stack marquee

ICON_DIR = os.path.join(ROOT, "tools", "icons")


def _icon_body(name: str) -> tuple[str, str]:
    """Return (viewBox, inner markup) for a vendored devicon file."""
    import re
    raw = open(os.path.join(ICON_DIR, f"{name}.svg"), encoding="utf-8").read()
    raw = re.sub(r"<\?xml.*?\?>", "", raw, flags=re.S)
    m = re.search(r"<svg[^>]*viewBox=\"([^\"]+)\"[^>]*>(.*)</svg>", raw, flags=re.S)
    if not m:
        raise ValueError(f"{name}: no viewBox")
    return m.group(1), m.group(2)


def stack(t) -> str:
    """A marquee of inlined tool icons.

    The icons have to be inlined rather than linked: an SVG that GitHub serves
    through <img> may not fetch external resources, so a remote <image> would
    render empty. The second copy of the row is drawn with <use> so the
    gradient ids inside each devicon file are never duplicated.
    """
    # Keep the order declared in fetch_icons.py — language, notebook, data,
    # modelling, storage, streaming, ops, web — rather than whatever order the
    # directory happens to list in.
    on_disk = {n[:-4] for n in os.listdir(ICON_DIR) if n.endswith(".svg")}
    try:
        from fetch_icons import ICONS
        names = [n for n, _ in ICONS if n in on_disk]
        names += sorted(on_disk - set(names))
    except ImportError:
        names = sorted(on_disk)
    size, gap = 52, 40
    stride = size + gap
    row_w = stride * len(names)
    h = 92
    secs = max(30, len(names) * 1.8)

    css = (
        f".row{{animation:slide {secs:.0f}s linear infinite}}"
        f"@keyframes slide{{from{{transform:translateX(0)}}"
        f"to{{transform:translateX(-{row_w}px)}}}}"
        "@media(prefers-reduced-motion:reduce){.row{animation:none}}"
    )
    b = f'  <style>{css}</style>\n  <defs>\n'
    for n in names:
        vb, inner = _icon_body(n)
        b += (f'    <g id="ic-{n}"><svg width="{size}" height="{size}" '
              f'viewBox="{vb}">{inner}</svg></g>\n')
    b += (f'    <linearGradient id="fade" x1="0" x2="1">'
          f'<stop offset="0" stop-color="#fff" stop-opacity="0"/>'
          f'<stop offset="0.07" stop-color="#fff" stop-opacity="1"/>'
          f'<stop offset="0.93" stop-color="#fff" stop-opacity="1"/>'
          f'<stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient>\n')
    b += (f'    <mask id="edge"><rect x="0" y="0" width="{W}" height="{h}" '
          f'fill="url(#fade)"/></mask>\n  </defs>\n')

    b += '  <g mask="url(#edge)">\n    <g class="row">\n'
    for copy in range(2):
        for i, n in enumerate(names):
            x = copy * row_w + i * stride
            b += f'      <use href="#ic-{n}" x="{x}" y="20"/>\n'
    b += '    </g>\n  </g>\n'
    return svg(h, b)


# ------------------------------------------------------------------ thanks

# Drawn here rather than borrowed. The reference everyone copies for this slot
# is a Sanrio character, which is not ours to put on a public profile.
BUNNY = [
    "........##........##........",
    ".......#oo#......#oo#.......",
    ".......#op#......#po#.......",
    ".......#op#......#po#.......",
    ".......#op#......#po#.......",
    ".......#oo#......#oo#.......",
    "......##oo##....##oo##......",
    "......#oooo######oooo#......",
    ".....#oooooooooooooooo#.....",
    "....#oooooooooooooooooo#....",
    "....#ooeeoooooooooeeooo#....",
    "....#ooeeoooooooooeeooo#....",
    "....#ooooooooeeoooooooo#....",
    "....#opoooooooooooooopo#....",
    ".....#oooooooooooooooo#.....",
    "......#oooooooooooooo#......",
    ".......#oooooooooooo#.......",
    "........############........",
]
PINK = "#e8a0a8"


def thanks(t) -> str:
    px = 7
    gw = len(BUNNY[0]) * px
    x0 = (W - gw) / 2
    y0 = 36
    # Outline and body share one colour, so the grid reads as a solid
    # silhouette; the eyes take the opposite tone so they stay visible on
    # either theme. `wash` would put the body within a shade of the page.
    fill = {"#": t["mark"], "o": t["mark"], "p": PINK, "e": t["markfg"]}

    css = (
        ".bob{animation:bob 3.2s ease-in-out infinite}"
        "@keyframes bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-5px)}}"
        ".shut{opacity:0;animation:blink 5s steps(1,end) infinite}"
        "@keyframes blink{0%,94%{opacity:0}95%,99%{opacity:1}100%{opacity:0}}"
        ".open{animation:blinkb 5s steps(1,end) infinite}"
        "@keyframes blinkb{0%,94%{opacity:1}95%,99%{opacity:0}100%{opacity:1}}"
        "@media(prefers-reduced-motion:reduce){.bob,.shut,.open{animation:none}"
        ".shut{opacity:0}.open{opacity:1}}"
    )
    b = f'  <style>{css}</style>\n  <g class="bob">\n'
    eyes = []
    for r, row in enumerate(BUNNY):
        for c, ch in enumerate(row):
            if ch == ".":
                continue
            x, y = x0 + c * px, y0 + r * px
            cell = (f'    <rect x="{x}" y="{y}" width="{px}" height="{px}" '
                    f'fill="{fill[ch]}"/>\n')
            if ch == "e":
                eyes.append((x, y))
            else:
                b += cell
    # Eyes as their own layers so a blink is a cross-fade, never a transform.
    b += '    <g class="open">\n'
    for x, y in eyes:
        b += f'      <rect x="{x}" y="{y}" width="{px}" height="{px}" fill="{t["markfg"]}"/>\n'
    b += '    </g>\n    <g class="shut">\n'
    for x, y in eyes:
        if y == y0 + 11 * px:                     # lower eye row only: a closed lid
            b += f'      <rect x="{x}" y="{y}" width="{px}" height="{px}" fill="{t["markfg"]}"/>\n'
    b += '    </g>\n  </g>\n'

    ty = y0 + len(BUNNY) * px + 44
    b += text(W / 2, ty, "THANKS FOR STOPPING BY", size=20, weight=700,
              fill="accent", font=MONO, spacing=3, anchor="middle", t=t)
    return svg(ty + 28, b)


VISUALS = {
    "hero": hero,
    "s01": lambda t: band("01", "whoami", t),
    "whoami": whoami,
    "s02": lambda t: band("02", "system map", t),
    "map": system_map,
    "s03": lambda t: band("03", "projects", t),
    "s04": lambda t: band("04", "stack & tools", t),
    "s05": lambda t: band("05", "telemetry", t),
    "telemetry": telemetry,
    "s06": lambda t: band("06", "contribution", t),
    "thanks": thanks,
}

# Superseded visuals. Removed on every run so the repo never ships an asset the
# README stopped referencing.
# Theme-independent: the tool icons are the same colours on either background,
# so one copy is generated and the README links it with a plain <img>.
NEUTRAL = {"stack": stack}

RETIRED = ("header", "method", "topsis", "work", "footer")


def main() -> None:
    for theme in THEMES:
        out = ROOT + ("/assets" if theme == "light" else "/assets/dark")
        os.makedirs(out, exist_ok=True)
        for name, fn in VISUALS.items():
            with open(os.path.join(out, f"{name}.svg"), "w", encoding="utf-8", newline="\n") as fh:
                fh.write(fn(THEMES[theme]))
        if theme == "light":
            for name, fn in NEUTRAL.items():
                with open(os.path.join(out, f"{name}.svg"), "w", encoding="utf-8", newline="\n") as fh:
                    fh.write(fn(THEMES[theme]))
        else:
            stale = os.path.join(out, "stack.svg")
            if os.path.exists(stale):
                os.remove(stale)
        for name in RETIRED:
            stale = os.path.join(out, f"{name}.svg")
            if os.path.exists(stale):
                os.remove(stale)
    print(f"wrote {len(VISUALS) * 2 + len(NEUTRAL)} files into assets/ and assets/dark/")


if __name__ == "__main__":
    main()
